create table if not exists research_runs (id uuid primary key default gen_random_uuid(), owner_id uuid not null references users(id) on delete cascade, profile_snapshot jsonb not null default '{}'::jsonb, sector text not null, geography text not null, engagement text not null, stage text not null default 'collection', status text not null default 'active', error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists research_runs_owner_idx on research_runs(owner_id, created_at desc);
create table if not exists evidence (id uuid primary key default gen_random_uuid(), run_id uuid not null references research_runs(id) on delete cascade, original_url text not null, canonical_url text not null, publisher text, employer text, role text, location text, observed_at timestamptz not null default now(), published_at timestamptz, excerpt text, duties jsonb not null default '[]'::jsonb, access_status text not null default 'inspected', provenance text not null default 'manual_url', facts jsonb not null default '[]'::jsonb, unknowns jsonb not null default '[]'::jsonb, created_at timestamptz not null default now());
create index if not exists evidence_run_idx on evidence(run_id, created_at);
create unique index if not exists evidence_run_url_unique on evidence(run_id, canonical_url);
create table if not exists opportunities (id uuid primary key default gen_random_uuid(), run_id uuid not null references research_runs(id) on delete cascade, title text not null, summary text not null, eligibility text not null default 'discovery_lead', scores jsonb not null default '{}'::jsonb, rationale jsonb not null default '[]'::jsonb, unknowns jsonb not null default '[]'::jsonb, created_at timestamptz not null default now());
create index if not exists opportunities_run_idx on opportunities(run_id);
